  const holoH = I.h - (big ? 112 : 40), cx = I.x + I.w / 2, cy = I.y + holoH / 2 + 2, sc = Math.min(I.w * 0.3, holoH * 0.44);
  c.save(); c.globalAlpha = hf <= 0.3 ? 0.55 + 0.45 * Math.sin(time * 8) : 1; drawShipHolo(c, cx, cy, sc, hp.hit > 0 ? '#ff5a6e' : hc); c.restore();
