  c.fillStyle = 'rgba(150,220,230,0.14)'; c.fillRect(I.x + 4, y1, bw, bhh); c.fillStyle = hc; c.fillRect(I.x + 4, y1, bw * hf, bhh);
  const y2 = y1 + (big ? 30 : 15);
