  c.fillStyle = 'rgba(150,220,230,0.14)'; c.fillRect(I.x + 4, y2, bw, bhh * 0.7); c.fillStyle = '#8ab4ff'; c.fillRect(I.x + 4, y2, bw * hp.shield / hp.shieldMax, bhh * 0.7);
