    const d = scanTgt && npcs.indexOf(scanTgt) >= 0 ? scanTgt.pos.distanceTo(rig.position) : 9999;
    if (d > 900){ scanT = -10; liveSay('Telsiz', 'Taramadan sıyrıldın.', '#7be0a4'); }
