  (S.ells||[]).forEach(e=>{ const g=new THREE.SphereGeometry(1,28,16,0,Math.PI*2,0,e.half?Math.PI/2:Math.PI); (e.mir?[1,-1]:[1]).forEach(sd=>{ const m=add(g); m.scale.set(e.rx,e.ry,e.rz); m.position.set(X(e.u),e.y,sd*(e.z||0)); }); });
