  const _cwA = new THREE.Vector3();
  const E = { l: w.children[0], r: w.children[1], t: w.children[2], b: w.children[3] }, cur = { l: 0, r: 0, t: 0, b: 0 };
  const _q = new THREE.Quaternion(), _v = new THREE.Vector3();
  window.__cw = cur;
