    L = spawnNpc('boss' + k, p, STATION); L.leader = true; L.boss = k; L.name = '★ ' + BOSS[k].ad; L.hull = L.hullMax = Math.round(1700 * (SYSC.hull || 1)); L.state = 'attack'; L.tgt = 'player'; L.atkT = time; L.provoked = true;
